def chiffrer_donnees_existantes(apps, schema_editor):
    """Chiffre les signatures du visage et les fichiers photo de la version précédente."""
    from pathlib import Path

    from django.conf import settings as reglages

    from pointage import chiffrement

    def chiffrer_fichier(nom):
        if not nom:
            return
        chemin = Path(reglages.MEDIA_ROOT) / nom
        if chemin.is_file():
            donnees = chemin.read_bytes()
            if not chiffrement.est_chiffre(donnees):
                chemin.write_bytes(chiffrement.chiffrer(donnees))

    for modele in ("Employe", "Pointage"):
        Modele = apps.get_model("pointage", modele)
        champ_photo = "photo_reference" if modele == "Employe" else "photo"
        for obj in Modele.objects.all():
            if obj.descripteur:
                obj.descripteur_chiffre = chiffrement.chiffrer_json(obj.descripteur)
                obj.save(update_fields=["descripteur_chiffre"])
            chiffrer_fichier(getattr(obj, champ_photo).name)


